// The CRM's delivery log lists the webhooks it gave up on, e.g. because n8n was down for longer
// than its 3 retries (L-016). Only those are re-sent. Records created with webhooks off (seeded test
// data) were never announced, so they are never in this list and never screened by accident.
// A row without a subject (logged before the CRM recorded one) can't be rebuilt: skipped here,
// still counted in the CRM's /stats.
const page = $input.first().json;
return (page.items || []).filter((d) => d.subject_id).map((d) => ({
  json: { delivery_id: d.id, event_id: d.event_id, application_id: d.subject_id, attempts: d.attempts, last_error: d.error },
}));

// One line per delivery this run touched (records in = records out). The CRM keeps the state:
// a delivery that still fails stays in its log and is tried again on the next run.
const outcomes = $input.all().map((it, i) => {
  const d = $('One item per delivery').itemMatching(i).json;
  const r = it.json;
  if (r.statusCode === undefined) return { ...d, result: 'CALL_FAILED', detail: String((r.error && r.error.message) || r.error || 'no response').slice(0, 200) };
  if (r.statusCode === 409) return { ...d, result: 'ALREADY_DELIVERED' }; // an overlapping run got there first
  if (r.statusCode !== 200) return { ...d, result: `HTTP_${r.statusCode}`, detail: r.body && r.body.error ? r.body.error.code : null };
  return { ...d, result: r.body.state === 'delivered' ? 'REDELIVERED' : 'STILL_FAILING', detail: r.body.error || null };
});
const problems = outcomes.filter((o) => !['REDELIVERED', 'ALREADY_DELIVERED'].includes(o.result));
// Successful runs aren't saved (one a minute would bury the real executions), failed ones are: so a
// redelivery that keeps failing shows up as a failed execution until someone fixes the cause.
if (problems.length) throw new Error(`${problems.length} of ${outcomes.length} redeliveries failed: ${JSON.stringify(problems).slice(0, 900)}`);
return [{ json: { checked: outcomes.length, redelivered: outcomes.filter((o) => o.result === 'REDELIVERED').length, outcomes } }];
